        let d = dst.name();
        let s1 = src1.map_or(IrExpr::Undef, VRegSlot::expr);
        let s2 = src2.map_or(IrExpr::Undef, VRegSlot::expr);
        let arr = dst.arrangement.label();
        let m = mnemonic.to_ascii_lowercase();

